PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?father ?fatherLabel ?alma ?almaLabel WHERE {
  dbr:Mate_Me61trovi07 ?pf ?father .
  FILTER(isIRI(?father))
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = 'en') }
  OPTIONAL {
    { ?father dbo:almaMater ?alma }
    UNION { ?father dbp:almaMater ?alma }
    UNION { ?father dbp:education ?alma }
    UNION { ?father dbp:training ?alma }
    UNION { ?father dbo:education ?alma }
    UNION { ?father dbp:studiedAt ?alma }
    UNION { ?father dbp:alumni ?alma }
  }
  OPTIONAL { ?alma rdfs:label ?almaLabel . FILTER(lang(?almaLabel) = 'en') }
}

